/** Letters that have no decomposition into a base letter plus accent, so they need their own replacement. */
const STANDALONE_LETTERS = {
  ß: 'ss', ẞ: 'SS',
  ø: 'o', Ø: 'O',
  æ: 'ae', Æ: 'AE',
  œ: 'oe', Œ: 'OE',
  đ: 'd', Đ: 'D',
  ł: 'l', Ł: 'L',
};

/** Returns the text with accented letters replaced by plain ones (é to e, ü to u, ß to ss), as the label printers only print ASCII. */
export function toPlainLetters(text) {
  return text
    .replace(/[ßẞøØæÆœŒđĐłŁ]/g, (letter, index) => {
      const plain = STANDALONE_LETTERS[letter];
      // A capital ligature starting a word in mixed case is written Ae, not AE (Ærøvej to Aerovej).
      const startsMixedCaseWord = plain.length === 2 && plain === plain.toUpperCase() && /\p{Ll}/u.test(text[index + 1] ?? '');
      return startsMixedCaseWord ? plain[0] + plain[1].toLowerCase() : plain;
    })
    .normalize('NFD')
    .replace(/\p{M}/gu, '');
}

/** Returns the lines of an address as they are printed: name, street, postcode and city, country. */
export function formatAddressLines(address) {
  const cityLine = `${normalizePostcode(address.postcode)} ${address.city}`;
  return [address.name, address.street.trim(), cityLine, address.country].map(toPlainLetters);
}

/** Returns a postcode in capitals, with single spaces and none around it. */
export function normalizePostcode(postcode) {
  return postcode.trim().toUpperCase().replace(/\s+/g, ' ');
}

